"""Plot latency CSV generated by latency_probe / latency_runner."""
import argparse
import os
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt


def parse_args():
    p = argparse.ArgumentParser(description="Plot latency results")
    p.add_argument("--csv", required=True)
    p.add_argument("--out-dir", default="charts")
    return p.parse_args()


def ensure_dir(d):
    os.makedirs(d, exist_ok=True)


def save_summary(df, out_dir):
    summary = df.groupby(["protocol", "payload", "qos", "tag"])["mean", "median", "std", "p95", "n"].mean().reset_index()
    summary_path = os.path.join(out_dir, "summary.csv")
    summary.to_csv(summary_path, index=False)
    print("Saved summary to", summary_path)


def plot_box(df, out_dir):
    plt.figure(figsize=(10, 6))
    sns.boxplot(data=df, x="payload", y="latency", hue="protocol")
    plt.title("Latency distribution by payload")
    plt.ylabel("Latency (ms)")
    plt.xlabel("Payload (bytes)")
    path = os.path.join(out_dir, "box_payload.png")
    plt.savefig(path, dpi=200, bbox_inches="tight")
    plt.close()


def plot_line(df, out_dir):
    plt.figure(figsize=(10, 6))
    sns.lineplot(data=df, x="payload", y="latency", hue="protocol", style="qos", markers=True)
    plt.title("Latency vs payload")
    plt.ylabel("Latency (ms)")
    plt.xlabel("Payload (bytes)")
    path = os.path.join(out_dir, "line_payload.png")
    plt.savefig(path, dpi=200, bbox_inches="tight")
    plt.close()


def explode_samples(df):
    # latency_probe stores stats only; to plot distributions we approximate with mean values.
    # If you want full distributions, modify latency_probe to store raw samples.
    records = []
    for _, row in df.iterrows():
        records.append({
            "protocol": row.protocol,
            "payload": row.payload,
            "qos": row.qos,
            "tag": row.tag,
            "latency": row.mean,
        })
    return pd.DataFrame(records)


def main():
    args = parse_args()
    ensure_dir(args.out_dir)
    df = pd.read_csv(args.csv)
    save_summary(df, args.out_dir)
    plot_df = explode_samples(df)
    plot_box(plot_df, args.out_dir)
    plot_line(plot_df, args.out_dir)
    print("Plots saved to", args.out_dir)


if __name__ == "__main__":
    main()
